package org.securemail.community;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.community.core.*;
import org.securemail.community.access.AccessControl;
import org.securemail.community.protocol.CommunityAuth;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.security.*;
import java.time.Clock;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Real separate SQLite bootstrap and service key files; no production configuration. */
class CommunityMainTest {
 @TempDir Path dir;
 KeyPair first,second;byte[] firstSeed,secondSeed;Map<String,String> options;
 @BeforeEach void setup()throws Exception {first=key();second=key();firstSeed=new byte[32];secondSeed=new byte[32];new SecureRandom().nextBytes(firstSeed);new SecureRandom().nextBytes(secondSeed);Files.write(dir.resolve("first.pub"),first.getPublic().getEncoded());Files.write(dir.resolve("second.pub"),second.getPublic().getEncoded());secret(dir.resolve("first.seed"),firstSeed);secret(dir.resolve("second.seed"),secondSeed);options=new LinkedHashMap<>(Map.of("--first-public",dir.resolve("first.pub").toString(),"--first-fingerprint",CommunityAuth.id(first.getPublic().getEncoded()),"--first-totp",dir.resolve("first.seed").toString(),"--second-public",dir.resolve("second.pub").toString(),"--second-fingerprint",CommunityAuth.id(second.getPublic().getEncoded()),"--second-totp",dir.resolve("second.seed").toString()));}
 @AfterEach void wipe(){Arrays.fill(firstSeed,(byte)0);Arrays.fill(secondSeed,(byte)0);}
 private static KeyPair key()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
 private static void secret(Path path,byte[] bytes)throws Exception {Files.write(path,bytes);try{Files.setPosixFilePermissions(path,PosixFilePermissions.fromString("rw-------"));}catch(UnsupportedOperationException unsupported){Assumptions.abort("This target fixture checks POSIX permissions; Windows ACL is a separate native gate");}}
 private String[] args(String action,Path target,Map<String,String> opts){List<String> result=new ArrayList<>(List.of(action,target.toString()));opts.forEach((k,v)->{result.add(k);result.add(v);});return result.toArray(String[]::new);}
 @Test void atomicInitCreatesFreshServiceIdentityAndEncryptedFactorsWithoutPrintingSecrets()throws Exception {Path target=dir.resolve("service");var captured=new ByteArrayOutputStream();CommunityMain.initialize(target,options,new PrintStream(captured,true,StandardCharsets.UTF_8));assertEquals("AEGIS-COMMUNITY-v1\n",Files.readString(target.resolve("INITIALIZED")));assertEquals(PosixFilePermissions.fromString("rwx------"),Files.getPosixFilePermissions(target));for(String file:List.of("service-private.pkcs8","service-public.x509","factor-kek.bin","INITIALIZED"))assertEquals(PosixFilePermissions.fromString("rw-------"),Files.getPosixFilePermissions(target.resolve(file)));
   byte[] publicKey=Files.readAllBytes(target.resolve("service-public.x509")),kek=Files.readAllBytes(target.resolve("factor-kek.bin"));assertFalse(CommunityAuth.id(publicKey).equals(CommunityAuth.id(first.getPublic().getEncoded())));String text=captured.toString(StandardCharsets.UTF_8);assertTrue(text.contains(Base64.getEncoder().encodeToString(publicKey)));assertFalse(text.contains(Base64.getEncoder().encodeToString(firstSeed)));assertFalse(text.contains(Base64.getEncoder().encodeToString(secondSeed)));assertFalse(text.contains(Base64.getEncoder().encodeToString(Files.readAllBytes(target.resolve("service-private.pkcs8")))));
   try(var store=new CommunityStore(target.resolve("community.sqlite"))){var access=new AccessControl(store,kek);assertTrue(access.isGlobalAdmin(CommunityAuth.id(first.getPublic().getEncoded())));assertTrue(access.isGlobalAdmin(CommunityAuth.id(second.getPublic().getEncoded())));store.tx(db->{access.verifySecondFactor(db,CommunityAuth.id(first.getPublic().getEncoded()),Totp.code(firstSeed,store.clock().millis()));return null;});assertTrue(store.verifyAudit());assertEquals(2L,store.tx(db->CommunityStore.count(db,"identities")).longValue());}
   Arrays.fill(kek,(byte)0);assertEquals(0,CommunityMain.run(new String[]{"--inspect",target.toString()},new PrintStream(new ByteArrayOutputStream()),System.err));
 }
 @Test void fingerprintsIndependentSeedsAndNewDirectoryAreMandatory()throws Exception {Path target=dir.resolve("service");Map<String,String> wrong=new HashMap<>(options);wrong.put("--first-fingerprint","0".repeat(64));assertThrows(IOException.class,()->CommunityMain.initialize(target,wrong,System.out));assertFalse(Files.exists(target));secret(dir.resolve("second.seed"),firstSeed);assertThrows(IOException.class,()->CommunityMain.initialize(target,options,System.out));assertFalse(Files.exists(target));secret(dir.resolve("second.seed"),secondSeed);Files.createDirectory(target);Files.writeString(target.resolve("keep"),"retain");assertThrows(IOException.class,()->CommunityMain.initialize(target,options,System.out));assertEquals("retain",Files.readString(target.resolve("keep")));}
 @Test void worldReadableFactorAndSymlinkDestinationAreRejected()throws Exception {Files.setPosixFilePermissions(dir.resolve("first.seed"),PosixFilePermissions.fromString("rw-r--r--"));Path target=dir.resolve("service");assertThrows(IOException.class,()->CommunityMain.initialize(target,options,System.out));assertFalse(Files.exists(target));Files.setPosixFilePermissions(dir.resolve("first.seed"),PosixFilePermissions.fromString("rw-------"));Path real=dir.resolve("real");Files.createDirectory(real);Files.createSymbolicLink(dir.resolve("linked"),real);assertThrows(IOException.class,()->CommunityMain.initialize(dir.resolve("linked/service"),options,System.out));assertFalse(Files.exists(real.resolve("service")));}
 @Test void operatorServeStartsActualSignedHttpAndStopsWithoutChangingRelay()throws Exception {
   Path target=dir.resolve("live-service");CommunityMain.initialize(target,options,new PrintStream(new ByteArrayOutputStream()));int port;try(var reservation=new java.net.ServerSocket(0,1,java.net.InetAddress.getLoopbackAddress())){port=reservation.getLocalPort();}
   Set<String> locations=new LinkedHashSet<>();for(Class<?> type:List.of(CommunityMain.class,CommunityAuth.class,Class.forName("org.sqlite.JDBC"),Class.forName("org.slf4j.LoggerFactory"),Class.forName("org.slf4j.nop.NOPServiceProvider")))locations.add(Path.of(type.getProtectionDomain().getCodeSource().getLocation().toURI()).toString());
   Path log=dir.resolve("operator-serve.log");Process process=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java").toString(),"-Xmx384m","-cp",String.join(File.pathSeparator,locations),CommunityMain.class.getName(),"--serve",target.toString(),"--port",Integer.toString(port)).redirectErrorStream(true).redirectOutput(log.toFile()).start();
   try {
     boolean listening=false;for(int n=0;n<70&&process.isAlive();n++){try(var socket=new java.net.Socket("127.0.0.1",port)){listening=true;break;}catch(IOException starting){Thread.sleep(100);}}assertTrue(listening,Files.readString(log));
     byte[] bytes=org.securemail.community.http.StrictJson.bytes(Map.of("action","community.me","data",Map.of()));String nonce=CommunityAuth.nonce(),audience=CommunityAuth.id(Files.readAllBytes(target.resolve("service-public.x509")));long time=System.currentTimeMillis();
     var connection=(java.net.HttpURLConnection)new java.net.URI("http://127.0.0.1:"+port+"/api/v1").toURL().openConnection(java.net.Proxy.NO_PROXY);connection.setConnectTimeout(3000);connection.setReadTimeout(5000);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setFixedLengthStreamingMode(bytes.length);connection.setRequestProperty("Content-Type","application/json");connection.setRequestProperty("AEGIS-Key",Base64.getEncoder().encodeToString(first.getPublic().getEncoded()));connection.setRequestProperty("AEGIS-Time",Long.toString(time));connection.setRequestProperty("AEGIS-Nonce",nonce);connection.setRequestProperty("AEGIS-Signature",Base64.getEncoder().encodeToString(CommunityAuth.sign(first.getPrivate(),CommunityAuth.requestBytes(audience,time,nonce,bytes))));
     try{try(var output=connection.getOutputStream()){output.write(bytes);}assertEquals(200,connection.getResponseCode());byte[] response;try(var input=connection.getInputStream()){response=input.readNBytes(65536);}assertTrue(CommunityAuth.verify(Files.readAllBytes(target.resolve("service-public.x509")),CommunityAuth.responseBytes(audience,nonce,response),Base64.getDecoder().decode(connection.getHeaderField("AEGIS-Signature"))));Map<String,Object> result=org.securemail.community.http.StrictJson.object(response,65536);assertEquals(true,result.get("ok"));assertEquals(true,((Map<?,?>)result.get("data")).get("isAdmin"));}finally{connection.disconnect();}
   }finally{process.destroy();if(!process.waitFor(7,java.util.concurrent.TimeUnit.SECONDS)){process.destroyForcibly();process.waitFor();}}
   try(var store=new CommunityStore(target.resolve("community.sqlite"))){assertTrue(store.verifyAudit());}String logged=Files.readString(log);assertFalse(logged.contains(Base64.getEncoder().encodeToString(firstSeed)));assertFalse(logged.contains(Base64.getEncoder().encodeToString(secondSeed)));
 }
 @Test void cliRejectsMalformedArgumentsAndKeyTamperingWithoutSecretDiagnostics()throws Exception {Path target=dir.resolve("service");var captured=new ByteArrayOutputStream();var out=new PrintStream(captured,true,StandardCharsets.UTF_8);assertEquals(1,CommunityMain.run(args("--init",target,Map.of()),out,out));assertFalse(Files.exists(target));assertEquals(0,CommunityMain.run(args("--init",target,options),out,out));byte[] wrong=key().getPublic().getEncoded();Files.write(target.resolve("service-public.x509"),wrong);assertEquals(1,CommunityMain.run(new String[]{"--inspect",target.toString()},out,out));assertFalse(captured.toString(StandardCharsets.UTF_8).contains("SQLException"));assertEquals(2,CommunityMain.run(new String[]{"--unknown"},out,out));}
}
